import com.holdmyspot.codexunleashed.scheduler.WindowsProcess;
import java.lang.foreign.Arena;
import java.lang.foreign.FunctionDescriptor;
import java.lang.foreign.Linker;
import java.lang.foreign.MemorySegment;
import java.lang.foreign.SymbolLookup;
import java.lang.foreign.ValueLayout;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.List;

/**
 * Exercises a packaged Windows process owner's binary standard streams and borrowed handles.
 */
public final class WindowsStreamsProbe
{
    /**
     * Runs the child fixture, or launches it through the public separate-stream operation.
     * The child copies binary input to stdout, writes a distinct stderr payload and exits 7.
     * The parent waits for whole-job completion, closes the owner, then writes through both
     * original output handles and reads the original input handle to establish continued use.
     *
     * @param arguments either child, or parent followed by an absolute new receipt-file path
     * @throws Throwable if arguments, native launch, stream access or the expected outcome fail
     */
    public static void main(String[] arguments) throws Throwable
    {
        if (arguments.length == 1 && arguments[0].equals("child"))
        {
            System.in.transferTo(System.out);
            System.out.flush();
            System.err.write(new byte[] {0, 13, 10, (byte)255, 42});
            System.err.flush();
            System.exit(7);
        }
        if (arguments.length != 2 || !arguments[0].equals("parent"))
            throw new IllegalArgumentException("Pass child, or parent and an absolute new receipt-file path");
        Path receipt = Path.of(arguments[1]);
        if (!receipt.isAbsolute() || Files.exists(receipt))
            throw new IllegalArgumentException("Receipt must be an absolute new file: " + receipt);

        try (var arena = Arena.ofConfined())
        {
            var symbols = SymbolLookup.libraryLookup("kernel32", arena);
            var getHandle = Linker.nativeLinker().downcallHandle(symbols.find("GetStdHandle").orElseThrow(),
                FunctionDescriptor.of(ValueLayout.ADDRESS, ValueLayout.JAVA_INT));
            var input = (MemorySegment)getHandle.invokeExact(-10);
            var output = (MemorySegment)getHandle.invokeExact(-11);
            var error = (MemorySegment)getHandle.invokeExact(-12);
            Path java = Path.of(System.getProperty("java.home"), "bin", "java.exe");
            var command = List.of(java.toString(), "--enable-native-access=ALL-UNNAMED", "-cp",
                System.getProperty("java.class.path"), WindowsStreamsProbe.class.getName(), "child");
            WindowsProcess.Result result;
            try (var process = WindowsProcess.start(command, receipt.getParent(), System.getenv(),
                input, output, error))
            {
                result = process.waitFor(Duration.ofSeconds(30));
            }
            if (result.rootExit() != 7 || result.aborted())
                throw new AssertionError("Unexpected child outcome: " + result);
            if (System.in.read() != -1)
                throw new AssertionError("Child did not consume all binary input");
            System.out.write("PARENT-STDOUT\n".getBytes(StandardCharsets.UTF_8));
            System.out.flush();
            System.err.write("PARENT-STDERR\n".getBytes(StandardCharsets.UTF_8));
            System.err.flush();
            if (System.out.checkError() || System.err.checkError())
                throw new AssertionError("Borrowed output handles became unusable after owner close");
            Files.writeString(receipt, "root_exit=7\naborted=false\nwhole_job_complete=true\nborrowed_input_eof=true\nborrowed_outputs_usable=true\n");
        }
    }
}
